  ${
    xpeq1i.1 $e |- A = B $.
    $( Equality theorem for cross product. $)
    xpeq1i $p |- ( A X. C ) = ( B X. C ) $=
      ( wceq cxp xpeq1 ax-mp ) ABEACFBCFEDABCGH $.
      $( [22-Dec-2008] $) $( [21-Dec-2008] $)

    $( Equality theorem for cross product. $)
    xpeq2i $p |- ( C X. A ) = ( C X. B ) $=
      ( wceq cxp xpeq2 ax-mp ) ABECAFCBFEDABCGH $.
      $( [22-Dec-2008] $) $( [21-Dec-2008] $)
  $}

  ${
    $d y z w A $.  $d y z w B $.  $d x y z w $.
    hbxp.1 $e |- ( y e. A -> A. x y e. A ) $.
    hbxp.2 $e |- ( y e. B -> A. x y e. B ) $.
    $( Bound-variable hypothesis builder for cross product. $)
    hbxp $p |- ( y e. ( A X. B ) -> A. x y e. ( A X. B ) ) $=
      ( vz vw cv cop wceq wcel wa wex wal cxp ax-17 hbel hban hbex elxp albii
      3imtr4i ) BIZGIZHIZJKZUECLZUFDLZMZMZHNZGNZUMAOUDCDPLZUNAOULAGUKAHUGUJAUGA
      QUHUIAABBUECUDUELAQERABBUFDUDUFLAQFRSSTTGHUDCDUAZUNUMAUOUBUC $.
