$(
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
             Real and complex numbers - basic operations
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
$)

  $( Declare symbols needed for some defined terms. $)
  $c - $. $( Subtraction (binary minus. $)
  $c -u $. $( Unary minus sign. $)
  $c <_ $. $( 'Less than or equal to' relation. $)
  $c NN $. $( The set of positive integers (blackboard bold N). $)
  $c NN0 $. $( The set of nonnegative integers (blackboard bold N_0). $)
  $c ZZ $. $( The set of integers (blackboard bold Z). $)
  $c QQ $. $( The set of rational numbers (blackboard bold Q). $)
  $c RR+ $. $( The set of positive reals (blackboard bold R^+). $)

  $( Introduce some defined terms for our axiom system. $)

  $( Extend class notation to include subtraction. $)
  cmin $a class - $.
  $( Extend class notation to include unary minus.  The symbol ` -u ` is
     not a class by itself but part of a compound class definition.  We
     do this rather than making it a formal function since it is so
     commonly used.  Note: We use different symbols for unary minus
     ( ` -u ` ) and subtraction ~ cmin ( ` - ` ) to prevent syntax ambiguity.
     For example, looking at the syntax definition ~ co , if we used the same
     symbol then " ` ( - A - B ) ` " could mean either " ` - A ` " minus
     " ` B ` ", or it could represent the (meaningless) operation of classes
     " ` - ` " and " ` - B ` " connected with "operation" " ` A ` ".  On the
     other hand, " ` ( -u A - B ) ` " is unambiguous. $)
  cneg $a class -u A $.
  $( Extend class notation to include division. $)
  cdiv $a class / $.

  $( Extend wff notation to include the 'less than or equal to' relation. $)
  cle $a class <_ $.
  $( Extend class notation to include the class of positive integers. $)
  cn $a class NN $.
  $( Extend class notation to include the class of nonnegative integers. $)
  cn0 $a class NN0 $.
  $( Extend class notation to include the class of integers. $)
  cz $a class ZZ $.
  $( Extend class notation to include the class of rationals. $)
  cq $a class QQ $.
  $( Extend class notation to include the class of positive reals. $)
  crp $a class RR+ $.


$(
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
        Some deductions from the field axioms for complex numbers
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
$)

  $( Alias for ~ axaddcl , for naming consistency with ~ addcli . $)
  addcl $p |- ( ( A e. CC /\ B e. CC ) -> ( A + B ) e. CC ) $=
    ( axaddcl ) ABC $.
    $( [10-Mar-2008] $) $( [10-Mar-2008] $)

  $( Alias for ~ axaddrcl , for naming consistency with ~ readdcli . $)
  readdcl $p |- ( ( A e. RR /\ B e. RR ) -> ( A + B ) e. RR ) $=
    ( axaddrcl ) ABC $.
    $( [10-Mar-2008] $) $( [10-Mar-2008] $)

  $( Alias for ~ axmulcl , for naming consistency with ~ mulcli . $)
  mulcl $p |- ( ( A e. CC /\ B e. CC ) -> ( A x. B ) e. CC ) $=
    ( axmulcl ) ABC $.
    $( [10-Mar-2008] $) $( [10-Mar-2008] $)

  $( Alias for ~ axmulrcl , for naming consistency with ~ remulcli . $)
  remulcl $p |- ( ( A e. RR /\ B e. RR ) -> ( A x. B ) e. RR ) $=
    ( axmulrcl ) ABC $.
    $( [10-Mar-2008] $) $( [10-Mar-2008] $)

  $( Alias for ~ axaddcom , for naming consistency with ~ addcomi . $)
  addcom $p |- ( ( A e. CC /\ B e. CC ) -> ( A + B ) = ( B + A ) ) $=
    ( axaddcom ) ABC $.
    $( [10-Mar-2008] $) $( [10-Mar-2008] $)

  $( Alias for ~ axmulcom , for naming consistency with ~ mulcomi . $)
  mulcom $p |- ( ( A e. CC /\ B e. CC ) -> ( A x. B ) = ( B x. A ) ) $=
    ( axmulcom ) ABC $.
    $( [10-Mar-2008] $) $( [10-Mar-2008] $)

  $( Alias for ~ axaddass , for naming consistency with ~ addassi . $)
  addass $p |- ( ( A e. CC /\ B e. CC /\ C e. CC ) ->
                 ( ( A + B ) + C ) = ( A + ( B + C ) ) ) $=
    ( axaddass ) ABCD $.
    $( [10-Mar-2008] $) $( [10-Mar-2008] $)

  $( Alias for ~ axmulass , for naming consistency with ~ mulassi . $)
  mulass $p |- ( ( A e. CC /\ B e. CC /\ C e. CC ) ->
                 ( ( A x. B ) x. C ) = ( A x. ( B x. C ) ) ) $=
    ( axmulass ) ABCD $.
    $( [10-Mar-2008] $) $( [10-Mar-2008] $)

  $( Alias for ~ axdistr , for naming consistency with ~ adddii . $)
  adddi $p |- ( ( A e. CC /\ B e. CC /\ C e. CC ) ->
                ( A x. ( B + C ) ) = ( ( A x. B ) + ( A x. C ) ) ) $=
    ( axdistr ) ABCD $.
    $( [10-Mar-2008] $) $( [10-Mar-2008] $)

  $( Alias for ~ ax0id , for naming consistency with ~ addid1i . $)
  addid1 $p |- ( A e. CC -> ( A + 0 ) = A ) $=
    ( ax0id ) AB $.
    $( [10-Mar-2008] $) $( [10-Mar-2008] $)

  $( Alias for ~ ax1id , for naming consistency with ~ mulid1i . $)
  mulid1 $p |- ( A e. CC -> ( A x. 1 ) = A ) $=
    ( ax1id ) AB $.
    $( [10-Mar-2008] $) $( [10-Mar-2008] $)

  $( The set of real numbers exists. $)
  reex $p |- RR e. V $=
    ( cr cc axcnex axresscn ssexi ) ABCDE $.
    $( [25-Sep-2004] $) $( [30-Jul-2004] $)

  $( A real number is a complex number. $)
  recn $p |- ( A e. RR -> A e. CC ) $=
    ( cr cc axresscn sseli ) BCADE $.
    $( [10-Aug-1999] $)

  ${
    recni.1 $e |- A e. RR $.
    $( A real number is a complex number. $)
    recni $p |- A e. CC $=
      ( cr cc axresscn sselii ) CDAEBF $.
      $( [1-Mar-1995] $)
  $}

  ${
    recnd.1 $e |- ( ph -> A e. RR ) $.
    $( Deduction from real number to complex number. $)
    recnd $p |- ( ph -> A e. CC ) $=
      ( cr wcel cc recn syl ) ABDEBFECBGH $.
      $( [26-Oct-1999] $)
  $}

  $( Hypothesis for weak deduction theorem to eliminate ` A =/= 0 ` . $)
    elimne0 $p |- if ( A =/= 0 , A , 1 ) =/= 0 $=
      ( cc0 wne c1 cif neeq1 ax1ne0 elimhyp ) ABCZIADEZBCDBCADAJBFDJBFGH $.
      $( [15-May-1999] $)

  $( The addition operation is a set. $)
  addex $p |- + e. V $=
    ( cc cxp caddc wf cvv wcel axaddopr axcnex xpex fex mp2an ) AABZACDLEFCEFGA
    AHHILAECJK $.
    $( [29-Nov-2004] $) $( [19-Oct-2004] $)

  $( The multiplication operation is a set. $)
  mulex $p |- x. e. V $=
    ( cc cxp cmul wf cvv wcel axmulopr axcnex xpex fex mp2an ) AABZACDLEFCEFGAA
    HHILAECJK $.
    $( [22-Oct-2004] $) $( [19-Oct-2004] $)

  $( Distributive law for complex numbers. $)
  adddir $p |- ( ( A e. CC /\ B e. CC /\ C e. CC ) ->
              ( ( A + B ) x. C ) = ( ( A x. C ) + ( B x. C ) ) ) $=
    ( cc wcel w3a caddc co cmul wceq adddi 3coml wa mulcom addcl sylan 3impa
    3adant2 3adant1 opreq12d 3eqtr4d ) ADEZBDEZCDEZFZCABGHZIHZCAIHZCBIHZGHZUFCI
    HZACIHZBCIHZGHUDUBUCUGUJJCABKLUBUCUDUKUGJZUFDEUDUNUBUCMUFCNABOPQUEULUHUMUIG
    UBUDULUHJUCACNRUCUDUMUIJUBBCNSTUA $.
    $( [11-Oct-2004] $) $( [10-Oct-2004] $)

  ${
    axi.1 $e |- A e. CC $.
    axi.2 $e |- B e. CC $.
    $( Closure law for addition. $)
    addcli $p |- ( A + B ) e. CC $=
      ( cc wcel caddc co addcl mp2an ) AEFBEFABGHEFCDABIJ $.
      $( [23-Nov-1994] $)

    $( Closure law for multiplication. $)
    mulcli $p |- ( A x. B ) e. CC $=
      ( cc wcel cmul co mulcl mp2an ) AEFBEFABGHEFCDABIJ $.
      $( [23-Nov-1994] $)

    $( Commutative law for addition. $)
    addcomi $p |- ( A + B ) = ( B + A ) $=
      ( cc wcel caddc co wceq addcom mp2an ) AEFBEFABGHBAGHICDABJK $.
      $( [23-Nov-1994] $)

    $( Commutative law for multiplication. $)
    mulcomi $p |- ( A x. B ) = ( B x. A ) $=
      ( cc wcel cmul co wceq mulcom mp2an ) AEFBEFABGHBAGHICDABJK $.
      $( [23-Nov-1994] $)

    ${
      axi.3 $e |- C e. CC $.
      $( Associative law for addition. $)
      addassi $p |- ( ( A + B ) + C ) = ( A + ( B + C ) ) $=
        ( cc wcel caddc co wceq addass mp3an ) AGHBGHCGHABIJCIJABCIJIJKDEFABCLM
        $.
        $( [23-Nov-1994] $)

      $( Associative law for multiplication. $)
      mulassi $p |- ( ( A x. B ) x. C ) = ( A x. ( B x. C ) ) $=
        ( cc wcel cmul co wceq mulass mp3an ) AGHBGHCGHABIJCIJABCIJIJKDEFABCLM
        $.
        $( [23-Nov-1994] $)

      $( Distributive law. $)
      adddii $p |- ( A x. ( B + C ) ) = ( ( A x. B ) + ( A x. C ) ) $=
        ( cc wcel caddc co cmul wceq adddi mp3an ) AGHBGHCGHABCIJKJABKJACKJIJLD
        EFABCMN $.
        $( [23-Nov-1994] $)

      $( Distributive law. $)
      adddiri $p |- ( ( A + B ) x. C ) = ( ( A x. C ) + ( B x. C ) ) $=
        ( cc wcel caddc co cmul wceq adddir mp3an ) AGHBGHCGHABIJCKJACKJBCKJIJL
        DEFABCMN $.
        $( [16-Feb-1995] $)

    $}
  $}

  $( 0 is a complex number. $)
  0cn $p |- 0 e. CC $=
    ( ci cmul co c1 caddc cc0 cc axi2m1 axicn mulcli ax1cn addcli eqeltrri ) AA
    BCZDECFGHNDAAIIJKLM $.
    $( [20-Feb-2005] $) $( [19-Feb-2005] $)

  $( Identity law for addition. $)
  addid2 $p |- ( A e. CC -> ( 0 + A ) = A ) $=
    ( cc wcel cc0 caddc co wceq 0cn addcom mpan addid1 eqtrd ) ABCZDAEFZADEFZAD
    BCMNOGHDAIJAKL $.
    $( [10-Aug-1999] $)

  ${
    addid1.1 $e |- A e. CC $.
    $( Identity law for addition. $)
    addid1i $p |- ( A + 0 ) = A $=
      ( cc wcel cc0 caddc co wceq addid1 ax-mp ) ACDAEFGAHBAIJ $.
      $( [23-Nov-1994] $)

    $( Identity law for addition. $)
    addid2i $p |- ( 0 + A ) = A $=
      ( cc wcel cc0 caddc co wceq addid2 ax-mp ) ACDEAFGAHBAIJ $.
      $( [23-Nov-1994] $)

    $( Identity law for multiplication. $)
    mulid1i $p |- ( A x. 1 ) = A $=
