    $( Restriction of a shifted sequence. $)
    shftres $p |- ( ( A e. C /\ B (_ CC ) ->
                  ( ( F shift A ) |` B ) Fn B ) $=
      ( cshi co cc wfn wss cres wcel fnssres shftfn sylan ) DAFGZHIBHJPBKBIACLH
      BPMACDENO $.
