  $( Declare the new symbol needed for continuous complex functions. $)
  $c -cn-> $.

  $( Extend class notation to include the operation which returns a class
     of continuous complex functions. $)
  ccncf $a class -cn-> $.

  ${
    $d a b f s x y z w $.
    $( Define the operation whose value is a class of continuous complex
       functions. $)
    df-cncf $a |- -cn-> = { <. <. a , b >. , s >. | ( ( a (_ CC /\ b (_ CC ) /\
      s = { f | ( f : a --> b /\ A. x e. a A. y e. RR+
      E. z e. RR+ A. w e. a ( ( abs ` ( x - w ) ) < z ->
      ( abs ` ( ( f ` x ) - ( f ` w ) ) ) < y ) ) } ) } $.
  $}

