    $( Existence implied by membership in a topological space.  This technical
       lemma, which can help eliminate unnecessary antecedents, uses the Axiom
       of Regularity (via ~ elirr ) along with definitional tricks. $)
    tpsex $p |- ( <. A , J >. e. TopSp -> ( A e. V /\ J e. V ) ) $=
      ( vy vx cop ctps wcel cvv wbr df-br wrel cv ctop cuni wceq wa copab
      relopab df-topsp releqi mpbir brrelexi sylbir wn elirr pm3.27 eqid
      topopn adantr eqeltrd mto jca elisset eqeq1 anbi2d eleq1 unieq eqeq2d
      anbi12d opelopabg eleq2i syl5bb pm5.21nii mtbir opprc2 eleq1d mtbiri
      con4i ) ABEZFGZAHGZBHGZVJABFIVKABFJABFFKCLZMGZDLZVMNZOZPZDCQZKVRDCRFVSDCS
      ZTUAZUBUCVLVJVLUDZVJAAEZFGZWDAMGZAANZOZPZWHAAGAUEWHAWFAWEWGUFWEWFAGWGAWFW
      FUGUHUIUJUKWDVKVKPZWHWDVKVKWDAAFIVKAAFJAAFWAUBUCZWJULWEWIWGWEVKVKAMUMZWKU
      LUIWIWCVSGWHWDVRVNAVPOZPWHDCAAHHVOAOVQWLVNVOAVPUNUOVMAOZVNWEWLWGVMAMUPWMV
      PWFAVMAUQURUSUTFVSWCVTVAVBVCVDWBVIWCFABVEVFVGVHUL $.
      $( [19-Jul-2006] $) $( [18-Jul-2006] $)

    $( Express the predicate "is a topological space." $)
    istps $p |- ( <. A , J >. e. TopSp <-> ( J e. Top /\ A = U. J ) ) $=
      ( vy vx cop ctps wcel cvv wa ctop cuni wceq tpsex pm3.27 uniexg adantr
      eqeltrd elisset jca cv copab eqeq1 anbi2d eleq1 unieq eqeq2d anbi12d
      opelopabg df-topsp eleq2i syl5bb pm5.21nii ) ABEZFGZAHGZBHGZIZBJGZABKZLZI
      ZABMVAUOUPVAAUSHURUTNURUSHGUTBJOPQURUPUTBJRPSUQUMCTZJGZDTZVBKZLZIZDCUAZGV
      AUNVGVCAVELZIVADCABHHVDALVFVIVCVDAVEUBUCVBBLZVCURVIUTVBBJUDVJVEUSAVBBUEUF
      UGUHFVHUMDCUIUJUKUL $.
      $( [20-Jul-2006] $) $( [18-Jul-2006] $)

    $( Express the predicate "is a topological space." $)
    istps2 $p |- ( <. A , J >. e. TopSp <-> ( ( J e. Top /\ J (_ P~ A )
                  /\ ( (/) e. J /\ A e. J ) ) ) $=
      ( ctop wcel cuni wceq wa cpw wss c0 cop ctps eqimss adantl 0opn adantr
      pm3.27 eqid topopn eqeltrrd jca ex unissel adantrl impbid1 eqcom sspwuni
      anbi1i 3bitr4g pm5.32i istps anass 3bitr4i ) BCDZABEZFZGUNBAHIZJBDZABDZGZ
      GZGABKLDUNUQGUTGUNUPVAUNUOAFZUOAIZUTGZUPVAUNVBVDUNVBVDUNVBGZVCUTVBVCUNUOA
      MNVEURUSUNURVBBOPVEUOABUNVBQUNUOBDVBBUOUORSPTUAUAUBVCUSVBURBAUCUDUEAUOUFU
      QVCUTBAUGUHUIUJABUKUNUQUTULUM $.
      $( [28-Jul-2006] $) $( [18-Jul-2006] $)

    $( A standard textbook definition of a topological space. $)
    istps3 $p |- ( <. A , J >. e. TopSp <-> ( ( J (_ P~ A /\ (/) e. J /\
                 A e. J ) /\ ( A. x ( x (_ J -> U. x e. J ) /\
                 A. x e. J A. y e. J ( x i^i y ) e. J ) ) ) $=
      ( cop ctps wcel ctop cpw wss wa c0 w3a cv cuni wi wal cin wral istps2
      anass ancom 3anass anbi1i cvv wb ssexg pwexg sylan2 3adant2 istopg syl
      pm5.32i 3bitr2i 3bitri ) CDEFGDHGZDCIZJZKLDGZCDGZKZKUPURVAKZKZURUSUTMZANZ
      DJVEODGPAQVEBNRDGBDSADSKZKZCDTUPURVAUAVCVBUPKVDUPKVGUPVBUBVDVBUPURUSUTUCU
      DVDUPVFVDDUEGZUPVFUFURUTVHUSURUQUEGVHUTDUQUEUGCDUHUIUJABUEDUKULUMUNUO $.
      $( [3-Aug-2006] $) $( [18-Jul-2006] $)

    $( A standard textbook definition of a topological space. $)
    istps4 $p |- ( <. A , J >. e. TopSp <-> ( ( J (_ P~ A /\ (/) e. J /\
       A e. J ) /\ ( A. x ( x (_ J -> U. x e. J ) /\ A. x ( ( x (_ J /\
       x =/= (/) /\ x e. Fin ) -> |^| x e. J ) ) ) ) $=
      ( vy cop ctps wcel cpw wss c0 w3a cv cuni wi wal cin wral wa wne cfn
      cint istps3 fiint anbi2i bitri ) BCEFGCBHIJCGBCGKZALZCIZUGMCGNAOZUGDLPCGD
      CQACQZRZRUFUIUHUGJSUGTGKUGUACGNAOZRZRADBCUBUKUMUFUJULUIADCUCUDUDUE $.
