$(
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
                     Basic metric space properties
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
$)

  $( Declare new constant symbols and define their syntactical properties. $)
  $c Met $.
  $c MetSp $.
  $c ball $.
  $c Open $.

  $( Extend class notation with the class of all metrics. $)
  cme $a class Met $.

  $( Extend class notation with the class of all metric spaces. $)
  cmt $a class MetSp $.

  $( Extend class notation with the metric space ball function. $)
  cbl $a class ball $.

  $( Extend class notation with a function mapping each metric space to the
     family of its open sets. $)
  copn $a class Open $.

  ${
    $d x y z w v u $.
    $( Define the (proper) class of all metrics.  (A metric space is the
       metric's base set paired with the metric; see ~ df-ms .  However, we
       will often also call the metric itself a "metric space.")  Equivalent
       to Definition 14-1.1 of [Gleason] p. 223.  See ~ ismsg for the property
       "is a metric space."  The 4 properties in Gleason's definition are
       shown by ~ met0 , ~ metgt0 , ~ metsym , and ~ mettri . $)
    df-met $a |- Met = { x | E. y ( x : ( y X. y ) --> RR /\
                 A. z e. y A. w e. y ( ( ( z x w ) = 0 <-> z = w ) /\
                 A. v e. y ( z x w ) <_ ( ( v x z ) + ( v x w ) ) ) ) } $.

    $( Define the (proper) class of all metric spaces. $)
    df-ms $a |- MetSp = { <. x , y >. | ( y e. Met /\ x = dom dom y ) } $.

    $( Define the metric space ball function.  See ~ blval for its value. $)
    df-bl $a |- ball = { <. x , y >. | ( x e. Met /\ y =
  { <. <. z , w >. , v >. | ( ( z e. dom dom x /\ w e. RR ) /\ ( 0 < w /\ v =
                { u e. dom dom x | ( z x u ) < w } ) ) } ) } $.

    $( Define a function whose value is the family of open sets of a metric
       space.  See ~ isopn for its main property. $)
    df-opn $a |- Open = { <. x , y >. | ( x e. Met /\ y = { z | ( z (_
            dom dom x /\ A. w e. z E. v e. ran ( ball ` x ) (
            w e. v /\ v (_ z ) ) } ) } $.

    $( The class of all metric spaces is a relation. $)
    msrel $p |- Rel MetSp $=
      ( vy vx cmt wrel cv cme wcel cdm wceq wa copab relopab df-ms releqi
      mpbir ) CDAEZFGBEPHHIJZBAKZDQBALCRBAMNO $.
      $( [28-Aug-2006] $) $( [28-Aug-2006] $)
  $}

