    $( A vector plus itself is two times the vector. $)
    vc2 $p |- ( ( W e. CVec /\ A e. X ) -> ( A G A ) = ( 2 S A ) ) $=
      ( cvc wcel wa c1 co c2 vcid opreq12d caddc cc wceq ax1cn vcdir mp3anr1
      mpanr1 df-2 opreq1i syl5req eqtr3d ) DIJZAEJZKZLABMZUKCMZAACMNABMZUJUKAUK
      ACABCDEFGHOZUNPUJLLQMZABMZULUMUHLRJZUIUPULSZTUHUQUQUIURTLLABCDEFGHUAUBUCN
