$(
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
         Pre-calculus and Cartesian geometry
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
$)

  $( Distance between the middle of a segment and one of its extremities is a
     positive real. $)
  dmse1 $p |- ( ( A e. RR /\ B e. RR /\ A =/= B ) ->
    ( ( abs ` ( A - B ) ) / 2 ) e. RR+ ) $=
    ( cr wcel wne w3a cmin co cabs cfv crp c2 wa cdiv cc cc0 absrpcl resubcl
    recnd 3adant3 wceq wn wb subeq0 recn syl2an biimpd necon3ad 3impia df-ne
    sylibr sylanc 2re 2pos elrpii jctir rpdivcl syl ) ACDZBCDZABEZFZABGHZIJZKDZ
    LKDZMVDLNHKDVBVEVFVCODZVCPEZVEVBVCQUSUTVGVAUSUTMZVCABRSTVBVCPUAZUBZVHUSUTVA
    VKVIVJABVIVJABUAZAODBODVJVLUCUSUTABUDAUEBUEUFUGUHUIVCPUJUKULLUMUNUOUPVDLUQU
    R $.
    $( [3-Jan-2008] $) $( [27-Dec-2007] $)

  $( Distance between the middle of a segment and one of its extremities is a
     positive real. $)
  dmse2 $p |- ( ( A e. RR /\ B e. RR /\ A < B ) ->
    ( ( abs ` ( A - B ) ) / 2 ) e. RR+ ) $=
    ( cr wcel wne cmin co cabs cfv c2 cdiv crp clt wbr dmse1 w3a ltne necomd
    syld3an3 ) ACDZBCDZABEABFGHIJKGLDABMNZABOTUAUBPBAABQRS $.
    $( [3-Jan-2008] $) $( [27-Dec-2007] $)

  $( The midpoint of a segment AB of the real line is a real. $)
  msr3 $p |- ( ( A e. RR /\ B e. RR ) ->
   ( B - ( ( abs ` ( A - B ) ) / 2 ) ) e. RR ) $=
    ( cr wcel cmin co cabs cfv c2 cdiv wa resubcl pm3.27 cc0 wne redivcl cc
    recnd abscl syl 2re a1i 2ne0 syl3anc sylanc ) BCDZABEFZGHZIJFZCDZBUIEFCDACD
    ZUFKZBUILUKUFMUHCDZICDZINOZUJULUHIPULUGQDUMULUGABLRUGSTUNULUAUBUOULUCUBUDUE
    $.
    $( [3-Jan-2008] $) $( [27-Dec-2007] $)

  $( The midpoint of a segment AB of the real line is a real.  (To FL:  This
     proof was shortened.  Also, it is too specialized, and set.mm size will
     be reduced if it is placed directly in the proof using it. -NM) $)
  msr4 $p |- ( ( A e. RR /\ B e. RR ) ->
    ( A + ( ( abs ` ( B - A ) ) / 2 ) ) e. RR ) $=
    ( cr wcel cmin co cabs cfv c2 cdiv caddc wa cc resubcl recnd ancoms abscl
    rehalfcl 3syl readdcl syldan ) ACDZBCDZBAEFZGHZIJFZCDZAUFKFCDUBUCLUDMDZUECD
    UGUCUBUHUCUBLUDBANOPUDQUERSAUFTUA $.
    $( [3-Jan-2008] $) $( [27-Dec-2007] $)

  $( Translation and inequality on the real line. $)
  ltsubpostb $p |- ( ( A e. RR /\ B e. RR+ ) -> ( A - B ) < A ) $=
    ( cr wcel cc0 clt wbr wa cmin co crp wi ltsubpos biimpd expcom imp32 elrp
    sylan2b ) ACDZBCDZEBFGZHABIJAFGZBKDSTUAUBTSUAUBLTSHUAUBBAMNOPBQR $.
    $( [3-Jan-2008] $) $( [27-Dec-2007] $)

  $( Translation and inequality on the real line. $)
  ltaddpos2tb $p |- ( ( A e. RR /\ B e. RR+ ) -> A < ( A + B ) ) $=
    ( cr wcel cc0 clt wbr wa caddc co crp wi ltaddpos biimpd expcom imp32 elrp
    sylan2b ) ACDZBCDZEBFGZHAABIJFGZBKDSTUAUBTSUAUBLTSHUAUBBAMNOPBQR $.
    $( [3-Jan-2008] $) $( [27-Dec-2007] $)

  $( The midpoint of a segment AB of the real line is on the "left" of
     ` B ` . $)
  mslb1 $p |- ( ( A e. RR /\ B e. RR /\ A < B  ) ->
     ( A + ( ( abs ` ( B - A ) ) / 2 ) ) < B ) $=
    ( cr wcel clt wbr w3a c2 cmul co cmin caddc cdiv cabs cfv wceq cc adddi
    2cn a1i recn 3ad2ant1 crp wa 3simpa anim12i ancoms abssub 3syl opreq1d
    dmse2 eqeltrd rpre syl3anc cc0 wne divcan2 subcl abscl 2ne0 cle absid
    resubcl 3adant3 ltle 3impia wb pm3.22 subge0 mpbird sylanc eqtrd opreq2d
    pm3.2i divmul mp3an3 readdcl 2re remulcl mpan adantr recnd rehalfcl syldan
    3simp3 3simp1 2times pm3.27 jca 3ad2ant2 pncan syl breqtrrd 3simp2 3brtr4d
