$(
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
                Filter limits
=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=-=
$)

  $c FilMap $.
  $( Extend class definition to include the neighborhood filter mapping
  function. $)
  cfilmap $a class FilMap $.

  $c fLimf $.
  $( Extend class definition to include the function for filter-based function
  limits. $)
  cflimf $a class fLimf $.

  $c fClus $.
  $( Extend class definition to include the cluster point function on filters.
  $)
  cfclus $a class fClus $.

  $c fClusf $.
  $( Extend class definition to include the function for cluster points of a
  function. $)
  cfclusf $a class fClusf $.

  ${
    $d f s t w x y z $.
    $( Define a function that takes a filter to a neighborhood filter of the
    range. $)
    df-filmap $a |- FilMap = { <. <. x , y >. , z >. | ( y e. fBas
    /\ z = { <. f , s >. | ( f : U. y --> x /\ s = ( filGen ` ( { w | E. t e. y
    w = ( f " t ) } u. { x } ) ) ) } ) } $.
  $}

  ${
    $d f s x y z $.
    $( Define a function that gives the limits of a function ` f ` in the
    filter sense. $)
    df-flimf $a |- fLimf = { <. <. x , y >. , z >. | ( x e. Top /\ y e. Fil /\
    z = { <. f , s >. | ( f : U. y --> U. x /\ s = ( ( fLim1 ` x ) ` ( ( U. x
    FilMap y ) ` f ) ) ) } ) } $.
  $}

  ${
    $d a b t x y $.
    $( Define a function that takes a filter in a topology to its set of
    cluster points. $)
    df-fclus $a |- fClus = { <. x , y >. | ( x e. Top /\ y = { <. a , b >. | (
    a e. Fil /\ U. a = U. x /\ b = |^|_ t e. a ( ( cls ` x ) ` t ) ) } ) } $.
  $}

  ${
    $d f s x y z $.
    $( Define a function that gives the cluster points of a function. $)
    df-fclusf $a |- fClusf = { <. <. x , y >. , z >. | ( x e. Top /\ y e. Fil
    /\ z = { <. f , s >. | ( f : U. y --> U. x /\ s = ( ( fClus ` x ) ` ( ( U.
    x FilMap y ) ` f ) ) ) } ) } $.
  $}

